    case 17: /* SQL_SMALL_RESULT */
    case 18: /* STRAIGHT_JOIN */
    case 19: /* CREATE */
    case 20: /* TEMPORARY */
    case 21: /* TABLE */
    case 22: /* INDEX */
    case 23: /* AGGREGATE */
    case 24: /* FUNCTION */
    case 25: /* LOGFILE */
    case 26: /* RESOURCE */
    case 27: /* UNDO */
    case 28: /* TABLESPACE */
    case 29: /* UNIQUE */
    case 30: /* FULLTEXT */
    case 31: /* SPATIAL */
    case 32: /* VIEW */
    case 33: /* OR */
    case 34: /* ALGORITHM */
    case 35: /* SQL */
    case 36: /* DEFINER */
    case 37: /* DATABASE */
    case 38: /* SCHEMA */
    case 39: /* EVENT */
    case 40: /* PROCEDURE */
    case 41: /* TRIGGER */
    case 42: /* USER */
    case 43: /* ROLE */
    case 44: /* SERVER */
    case 45: /* DROP */
    case 46: /* TABLES */
    case 47: /* PREPARE */
    case 48: /* ALTER */
    case 49: /* INSTANCE */
    case 50: /* RENAME */
    case 51: /* TO */
    case 52: /* MASTER */
    case 53: /* TRUNCATE */
    case 54: /* LOAD */
    case 55: /* DATA */
    case 56: /* XML */
    case 57: /* INTO */
    case 58: /* CACHE */
    case 59: /* LOW_PRIORITY */
    case 60: /* LOCAL */
    case 61: /* CONCURRENT */
    case 62: /* IGNORE */
    case 63: /* REPLACE */
    case 64: /* LP */
    case 65: /* RP */
    case 66: /* START */
    case 67: /* TRANSACTION */
    case 68: /* REPLICA */
    case 69: /* SLAVE */
    case 70: /* GROUP_REPLICATION */
    case 71: /* READ */
    case 72: /* WITH */
    case 73: /* WRITE */
